// Q&A content — full syllabus. `download: true` shows the PDF button (Java, Python, AWS).
// level: basic | inter | adv

export const qaTopics = [
  {
    id: 'java',
    label: 'Java',
    icon: '☕',
    download: true,
    items: [
      { level: 'basic', q: 'What is the difference between JDK, JRE and JVM?', a: 'JVM (Java Virtual Machine) executes bytecode and makes Java platform independent. JRE (Java Runtime Environment) = JVM + core libraries to RUN Java apps. JDK (Java Development Kit) = JRE + development tools (compiler javac, debugger) to DEVELOP Java apps.' },
      { level: 'basic', q: 'Why is Java called platform independent?', a: 'Java source is compiled into bytecode (.class), not machine code. This bytecode runs on any device with a JVM, so the same program runs on Windows, Linux or Mac — "Write Once, Run Anywhere". The JVM is platform dependent, your code is not.' },
      { level: 'basic', q: 'Difference between == and .equals()?', a: '== compares references (same object in memory). .equals() compares content/value. Two different String objects with the same text are == false but .equals() true. Use .equals() for value comparison.' },
      { level: 'basic', q: 'What is the difference between an array and an ArrayList?', a: 'An array has fixed size and can hold primitives or objects. An ArrayList is dynamic (auto-resizing), holds only objects (autoboxes primitives), and provides methods like add/remove. Arrays are faster and use less memory; ArrayList is more flexible.' },
      { level: 'basic', q: 'What are access modifiers in Java?', a: 'private (accessible only within the class), default/package-private (within the same package), protected (same package + subclasses), and public (accessible everywhere). They control encapsulation and visibility.' },
      { level: 'inter', q: 'Difference between overloading and overriding?', a: 'Overloading = same method name, different parameters, same class — resolved at COMPILE time (static polymorphism). Overriding = subclass redefines a parent method with the same signature — resolved at RUNTIME (dynamic polymorphism).' },
      { level: 'inter', q: 'Why is String immutable in Java?', a: 'For security, thread-safety (shared without sync), String-pool caching (reuse of literals), and reliable hashcodes (safe HashMap keys). Any "modification" creates a new String object.' },
      { level: 'inter', q: 'ArrayList vs LinkedList?', a: 'ArrayList uses a dynamic array: fast random access O(1), slow middle insert/delete O(n). LinkedList uses nodes: fast insert/delete O(1) once positioned, slow access O(n). Use ArrayList for reads, LinkedList for frequent inserts/deletes.' },
      { level: 'inter', q: 'How does HashMap work internally?', a: 'It stores entries in an array of buckets. The key\'s hashCode() is hashed to a bucket index. On collision, entries form a linked list that converts to a balanced tree after 8 entries (Java 8+). get/put are O(1) on average; equals() resolves the exact key.' },
      { level: 'inter', q: 'Explain the equals() and hashCode() contract.', a: 'If two objects are equal by equals(), they must return the same hashCode(). If you override equals() you must override hashCode() too — otherwise objects behave incorrectly as keys in HashMap/HashSet (equal objects landing in different buckets).' },
      { level: 'inter', q: 'Checked vs unchecked exceptions?', a: 'Checked (IOException, SQLException) are checked at compile time — you must handle or declare them. Unchecked (RuntimeException subclasses like NullPointerException, ArithmeticException) occur at runtime and are not enforced by the compiler.' },
      { level: 'inter', q: 'Purpose of the finally block?', a: 'finally always executes (even after a return in try/catch), so it is used for cleanup like closing files, DB connections or streams. It only skips on System.exit() or a JVM crash. try-with-resources is a cleaner alternative.' },
      { level: 'inter', q: 'Difference between interface and abstract class?', a: 'An abstract class can have constructors, instance fields, and both abstract and concrete methods; a class extends only one. An interface is a contract (constants + method signatures; default/static since Java 8); a class can implement many. Abstract class for shared state, interface for capability.' },
      { level: 'inter', q: 'What are Comparable and Comparator?', a: 'Comparable defines a class\'s natural ordering via compareTo() (one way to sort). Comparator is a separate object defining custom orderings via compare() (many ways to sort, e.g. by name or by age) without modifying the class.' },
      { level: 'adv', q: 'Difference between process and thread; how do you create a thread?', a: 'A process has its own memory; threads share process memory and are lighter. Create a thread by extending Thread, or (preferred) implementing Runnable/Callable passed to a Thread or ExecutorService. Callable returns a value and can throw checked exceptions via Future.' },
      { level: 'adv', q: 'What are synchronized and volatile?', a: 'synchronized gives mutual exclusion (one thread at a time on a lock) plus visibility, preventing race conditions. volatile only guarantees visibility (reads/writes go to main memory) but not atomicity. Use volatile for simple flags, synchronized for compound actions.' },
      { level: 'adv', q: 'Explain the Java 8 Stream API with an example.', a: 'Streams process collections declaratively via a pipeline of intermediate (filter, map, sorted) and terminal (collect, reduce, forEach) operations, with lazy evaluation and parallel support. Example: list.stream().filter(u -> u.getAge() > 18).map(User::getName).collect(Collectors.toList());' },
      { level: 'adv', q: 'What is a functional interface and a lambda?', a: 'A functional interface has exactly one abstract method (Runnable, Comparator, Predicate) and may be marked @FunctionalInterface. A lambda is a concise implementation of that method: (a, b) -> a + b. This lets you pass behavior as data and powers Streams.' },
      { level: 'adv', q: 'How does garbage collection work?', a: 'The JVM automatically reclaims memory of unreachable heap objects using generational collection: new objects go to the Young generation (Eden + Survivor); survivors are promoted to Old. Minor GC cleans Young, Full GC cleans everything. You cannot force it — System.gc() is only a hint.' },
      { level: 'adv', q: 'Explain final, finally and finalize.', a: 'final is a keyword: a final variable is a constant, a final method cannot be overridden, a final class cannot be extended. finally is a block that always runs for cleanup. finalize() was a method called before GC (now deprecated) — do not rely on it.' },
    ],
  },

  {
    id: 'python',
    label: 'Python',
    icon: '🐍',
    download: true,
    items: [
      { level: 'basic', q: 'Is Python compiled or interpreted? Typed how?', a: 'Python is interpreted (compiled to bytecode, then run by the Python VM) and dynamically typed (types checked at runtime, no declarations). It is also strongly typed — no silent odd conversions like "1" + 1.' },
      { level: 'basic', q: 'List vs tuple vs set vs dict?', a: 'List [] — ordered, mutable, duplicates. Tuple () — ordered, immutable. Set {} — unordered, unique. Dict {k:v} — key-value, keys unique, insertion-ordered since 3.7. Choose by need: tuples for fixed data, sets for uniqueness, dicts for lookups.' },
      { level: 'basic', q: 'What are mutable and immutable types?', a: 'Mutable objects can change in place: list, dict, set. Immutable cannot: int, float, str, tuple, frozenset. Immutability matters for dict keys (must be hashable) and avoiding surprising side effects.' },
      { level: 'basic', q: 'What is the difference between "is" and "=="?', a: '== checks value equality (same content). is checks identity (same object in memory). Use == for comparisons; reserve is for singletons like None: if x is None.' },
      { level: 'inter', q: 'What are *args and **kwargs?', a: '*args collects extra positional arguments into a tuple; **kwargs collects extra keyword arguments into a dict. They allow a function to accept a variable number of arguments and to forward them to other functions.' },
      { level: 'inter', q: 'What is a list comprehension?', a: 'A concise way to build a list: [x*x for x in range(5) if x % 2 == 0]. It is more readable and often faster than a manual loop with append. Similar syntax exists for dicts/sets, and () gives a lazy generator expression.' },
      { level: 'inter', q: 'Shallow copy vs deep copy?', a: 'A shallow copy (copy.copy) copies the outer object but shares nested references — changing a nested item affects both. A deep copy (copy.deepcopy) recursively copies everything, so the copies are fully independent.' },
      { level: 'inter', q: 'What are Python decorators?', a: 'A decorator is a function that takes another function and extends its behavior without modifying it, applied with @decorator. Common uses: logging, timing, authentication, caching. Built-ins include @staticmethod, @classmethod, @property.' },
      { level: 'adv', q: 'What is the GIL and why does it matter?', a: 'The Global Interpreter Lock lets only one thread execute Python bytecode at a time in CPython, so threads do not give true parallelism for CPU-bound work — use multiprocessing there. For I/O-bound work threads/asyncio still help because the GIL releases during I/O.' },
      { level: 'adv', q: 'What are generators and yield?', a: 'A generator function uses yield to produce values lazily, one at a time, keeping state between calls without storing the whole sequence — memory efficient for large/streaming data. Iterating resumes after the last yield.' },
      { level: 'adv', q: 'Decorators vs context managers?', a: 'Decorators wrap a function to add behavior around every call. Context managers manage setup/teardown around a block using with and __enter__/__exit__ (e.g. with open(f) as file auto-closes it). Different problems, both cut boilerplate.' },
      { level: 'inter', q: 'How would you connect Python to AWS?', a: 'Using boto3, the AWS SDK for Python — clients for S3, Lambda, Rekognition, etc. In my serverless emotion project boto3 handled S3 and Rekognition calls inside Lambda, with credentials from the Lambda IAM role (never hardcoded).' },
    ],
  },

  {
    id: 'dsa',
    label: 'Data Structures',
    icon: '🧮',
    download: false,
    items: [
      { level: 'basic', q: 'What is time complexity / Big-O?', a: 'Big-O describes how running time or space grows with input size in the worst case. Common orders: O(1), O(log n), O(n), O(n log n), O(n²). It lets you compare algorithms independent of hardware.' },
      { level: 'basic', q: 'Array vs Linked List?', a: 'Array: contiguous memory, O(1) index access, costly insert/delete (shifting), fixed size. Linked List: nodes with pointers, O(1) insert/delete once positioned, O(n) access, extra pointer memory.' },
      { level: 'basic', q: 'Stack vs Queue?', a: 'Stack is LIFO (push/pop from the top) — used in recursion, undo, expression evaluation. Queue is FIFO (enqueue at rear, dequeue from front) — used in scheduling, BFS, buffering.' },
      { level: 'inter', q: 'What is a hash table and how does it handle collisions?', a: 'A hash table maps keys to array indices via a hash function for O(1) average lookup. Collisions (two keys → same index) are handled by chaining (a list per bucket) or open addressing (probing for the next free slot).' },
      { level: 'inter', q: 'Explain binary tree traversals.', a: 'Inorder (Left, Root, Right — gives sorted order for a BST), Preorder (Root, Left, Right — copy a tree), Postorder (Left, Right, Root — delete a tree), and Level-order/BFS (level by level using a queue).' },
      { level: 'inter', q: 'What is a binary search tree (BST)?', a: 'A tree where each node\'s left subtree has smaller values and right subtree larger values. Search/insert/delete are O(log n) if balanced, O(n) if skewed. Balanced variants (AVL, Red-Black) guarantee O(log n).' },
      { level: 'inter', q: 'When would you use a HashMap vs a TreeMap?', a: 'HashMap gives O(1) average operations but no ordering. TreeMap keeps keys sorted (O(log n)) and supports range queries (floorKey, ceilingKey). Use HashMap for fast lookups, TreeMap for ordered traversal/range operations.' },
      { level: 'adv', q: 'How is a graph represented and traversed?', a: 'As an adjacency list (space-efficient for sparse graphs) or adjacency matrix (fast edge checks, dense graphs). Traversals: BFS (queue, shortest path in unweighted graphs) and DFS (stack/recursion, cycle detection, topological sort). Both are O(V+E).' },
      { level: 'adv', q: 'What is a heap and where is it used?', a: 'A heap is a complete binary tree where each parent is smaller (min-heap) or larger (max-heap) than its children. It gives O(1) access to min/max and O(log n) insert/remove. Used for priority queues, heap sort, and Dijkstra\'s algorithm.' },
    ],
  },

  {
    id: 'algorithms',
    label: 'Algorithms',
    icon: '⚙️',
    download: false,
    items: [
      { level: 'basic', q: 'Explain binary search.', a: 'Binary search finds an element in a SORTED array in O(log n) by repeatedly halving the range: compare the middle; go left if smaller, right if larger. Much faster than linear search O(n), but the data must be sorted.' },
      { level: 'basic', q: 'Compare Bubble, Merge and Quick sort.', a: 'Bubble sort is O(n²), simple but slow. Merge sort is O(n log n), stable, uses extra space, divide-and-conquer. Quick sort is O(n log n) average (O(n²) worst), in-place, usually fastest in practice. Merge is preferred when stability matters.' },
      { level: 'inter', q: 'What is recursion and what is a base case?', a: 'Recursion is a function calling itself to solve smaller subproblems. The base case is the stopping condition that prevents infinite calls (e.g. factorial(0) = 1). Without it you get a stack overflow.' },
      { level: 'inter', q: 'BFS vs DFS — when to use which?', a: 'BFS explores level by level using a queue — best for shortest path in unweighted graphs and level-order needs. DFS goes deep using recursion/stack — best for topological sort, cycle detection, connected components, and path existence.' },
      { level: 'inter', q: 'What is the difference between greedy and dynamic programming?', a: 'Greedy makes the locally optimal choice at each step and never reconsiders — fast but not always globally optimal. DP explores overlapping subproblems and stores results to guarantee the optimal solution. Greedy works when a problem has the greedy-choice property.' },
      { level: 'adv', q: 'What is dynamic programming?', a: 'DP solves problems with overlapping subproblems and optimal substructure by storing subresults to avoid recomputation. Two styles: top-down (recursion + memoization) and bottom-up (tabulation). Examples: Fibonacci, 0/1 knapsack, LCS, coin change.' },
      { level: 'adv', q: 'Explain the sliding window technique.', a: 'A pattern that maintains a window (subarray/substring) over data and slides it to avoid recomputing from scratch — turning an O(n²) brute force into O(n). Used for problems like max sum of k elements, longest substring without repeats.' },
      { level: 'adv', q: 'What is Dijkstra\'s algorithm?', a: 'A greedy algorithm that finds the shortest path from a source to all nodes in a weighted graph with non-negative edges, using a min-priority queue to always expand the closest unvisited node. Complexity O((V+E) log V). For negative edges use Bellman-Ford.' },
    ],
  },

  {
    id: 'dbms',
    label: 'DBMS / SQL',
    icon: '🗄️',
    download: false,
    items: [
      { level: 'basic', q: 'Difference between primary key and foreign key?', a: 'A primary key uniquely identifies each row and cannot be null. A foreign key references another table\'s primary key, creating a relationship and enforcing referential integrity.' },
      { level: 'basic', q: 'What are the ACID properties?', a: 'Atomicity (all or nothing), Consistency (valid state to valid state), Isolation (concurrent transactions don\'t interfere), Durability (committed data survives failures). They guarantee reliable transactions.' },
      { level: 'basic', q: 'DELETE vs TRUNCATE vs DROP?', a: 'DELETE removes rows (WHERE allowed, logged, rollback-able). TRUNCATE removes all rows fast (no WHERE, resets identity). DROP removes the whole table (structure + data). DELETE is DML; TRUNCATE and DROP are DDL.' },
      { level: 'basic', q: 'WHERE vs HAVING?', a: 'WHERE filters rows before grouping and cannot use aggregates. HAVING filters groups after GROUP BY and can use aggregates like COUNT() or SUM(). They are often used together.' },
      { level: 'inter', q: 'Explain the types of JOINs.', a: 'INNER (matching rows in both), LEFT (all left + matches), RIGHT (all right + matches), FULL OUTER (all rows from both), SELF (table joined to itself), CROSS (cartesian product).' },
      { level: 'inter', q: 'What is normalization? Explain 1NF, 2NF, 3NF.', a: '1NF: atomic values, no repeating groups. 2NF: 1NF + no partial dependency on part of a composite key. 3NF: 2NF + no transitive dependency. It reduces redundancy and update anomalies.' },
      { level: 'inter', q: 'What is an index and its trade-off?', a: 'An index (usually a B-Tree) speeds up searches by avoiding full scans. Trade-off: it uses storage and slows INSERT/UPDATE/DELETE because it must be maintained. Index columns used in WHERE, JOIN and ORDER BY.' },
      { level: 'adv', q: 'What are transaction isolation levels?', a: 'Read Uncommitted (dirty reads possible), Read Committed (no dirty reads), Repeatable Read (no non-repeatable reads), Serializable (fully isolated). Higher isolation = more consistency but less concurrency.' },
      { level: 'adv', q: 'Clustered vs non-clustered index?', a: 'A clustered index defines the physical row order — one per table (often the primary key). A non-clustered index is a separate structure with pointers to rows — you can have many. Clustered is faster for range scans on the key.' },
      { level: 'adv', q: 'How do you optimize a slow SQL query?', a: 'Add indexes on filtered/joined columns, avoid SELECT *, analyze with EXPLAIN, reduce joins/subqueries, use caching and pagination, fix N+1 queries, and denormalize where reads dominate. Measure before and after.' },
    ],
  },

  {
    id: 'mongodb',
    label: 'MongoDB / NoSQL',
    icon: '🍃',
    download: false,
    items: [
      { level: 'basic', q: 'What is NoSQL and how is MongoDB different from MySQL?', a: 'NoSQL is non-relational with flexible schemas and horizontal scaling. MongoDB is a document database storing JSON-like documents in collections, while MySQL stores rows in fixed-schema tables with relations. MongoDB suits changing schemas and scale; MySQL suits strong relationships and transactions.' },
      { level: 'basic', q: 'What is a document and a collection in MongoDB?', a: 'A document is a JSON/BSON record (key-value pairs, can be nested) — like a row. A collection is a group of documents — like a table, but schema-less so documents can differ. Databases contain collections.' },
      { level: 'inter', q: 'Embedding vs referencing in MongoDB?', a: 'Embedding stores related data inside one document (fast reads, good for one-to-few, data that\'s read together). Referencing stores an ID pointing to another document (avoids duplication, good for one-to-many/many-to-many and large or frequently-changing data).' },
      { level: 'inter', q: 'What is SQL vs NoSQL — when to use which?', a: 'SQL (MySQL) for structured data, complex relationships and ACID transactions. NoSQL (MongoDB) for flexible/changing schemas, large scale, high write throughput and horizontal scaling with eventual consistency. Choose by data shape and consistency needs.' },
      { level: 'adv', q: 'Explain the CAP theorem.', a: 'In a distributed system you can guarantee only two of Consistency, Availability and Partition-tolerance at once. Since network partitions are unavoidable, systems trade off consistency vs availability — MongoDB is typically CP, while some NoSQL stores favor AP.' },
      { level: 'adv', q: 'What are sharding and replica sets?', a: 'Sharding partitions data horizontally across servers to scale writes and storage. A replica set keeps copies of data on multiple nodes for high availability and automatic failover (one primary, several secondaries). Together they give scalability and reliability.' },
    ],
  },

  {
    id: 'os',
    label: 'Operating Systems',
    icon: '🖥️',
    download: false,
    items: [
      { level: 'basic', q: 'What is a process and a thread?', a: 'A process is a program in execution with its own memory. A thread is the smallest execution unit within a process; threads share the process memory but have their own stack. Threads are lighter than processes.' },
      { level: 'basic', q: 'What are the states of a process?', a: 'New, Ready (waiting for CPU), Running (executing), Waiting/Blocked (waiting on I/O), and Terminated. The scheduler moves processes between Ready and Running.' },
      { level: 'inter', q: 'Explain CPU scheduling algorithms.', a: 'FCFS (simple, convoy effect), SJF (optimal average wait, needs burst prediction), Priority (may starve low priority), Round Robin (time quantum, fair for time-sharing). Preemptive versions allow interruption.' },
      { level: 'inter', q: 'What is a deadlock and its four conditions?', a: 'A deadlock is when processes wait forever for resources held by each other. Conditions: Mutual Exclusion, Hold and Wait, No Preemption, Circular Wait. Break any one to prevent it (prevention, avoidance via Banker\'s, detection, recovery).' },
      { level: 'inter', q: 'Mutex vs semaphore?', a: 'A mutex is a lock allowing one thread into a critical section (ownership: the locker unlocks). A semaphore is a signaling counter allowing N threads (counting) or acting as a binary lock; it can also signal between threads.' },
      { level: 'adv', q: 'What is virtual memory and paging?', a: 'Virtual memory lets programs use more memory than physical RAM by keeping part on disk. Paging splits memory into fixed-size pages/frames mapped via a page table. A page fault occurs when a needed page isn\'t in RAM and must be loaded.' },
      { level: 'adv', q: 'Explain page replacement algorithms.', a: 'When memory is full, an existing page is evicted. FIFO (oldest out), LRU (least recently used — good, needs tracking), Optimal (evict page used farthest in future — theoretical best). LRU is a common practical choice.' },
      { level: 'adv', q: 'What is thrashing?', a: 'Thrashing is when the system spends more time swapping pages than executing, causing CPU utilization to collapse. It happens with too many processes and too little RAM. Fix by reducing multiprogramming or adding memory (working-set model).' },
    ],
  },

  {
    id: 'networks',
    label: 'Computer Networks',
    icon: '🌐',
    download: false,
    items: [
      { level: 'basic', q: 'TCP vs UDP?', a: 'TCP is connection-oriented, reliable, ordered and error-checked (handshake, acknowledgments) — used for web, email, file transfer. UDP is connectionless, fast, no delivery guarantee — used for streaming, gaming, DNS.' },
      { level: 'basic', q: 'What are the OSI layers?', a: 'Seven layers: Physical, Data Link, Network, Transport, Session, Presentation, Application. Each serves the one above and is served by the one below. TCP/IP condenses these into four practical layers.' },
      { level: 'inter', q: 'What happens when you type a URL and press Enter?', a: 'DNS resolves the domain to an IP; a TCP connection is established (3-way handshake); for HTTPS a TLS handshake sets up encryption; the browser sends an HTTP request; the server responds; the browser renders HTML/CSS/JS and fetches more resources.' },
      { level: 'inter', q: 'HTTP vs HTTPS?', a: 'HTTP sends data in plaintext (port 80). HTTPS layers HTTP over TLS/SSL (port 443), encrypting data in transit and authenticating the server via certificates — protecting against eavesdropping and tampering.' },
      { level: 'adv', q: 'Explain the TCP 3-way handshake.', a: 'To open a connection: client sends SYN, server replies SYN-ACK, client sends ACK. This synchronizes sequence numbers and confirms both sides can send/receive before data transfer begins.' },
      { level: 'adv', q: 'What is DNS and how does it work?', a: 'DNS translates domain names into IP addresses. A resolver queries root, TLD and authoritative name servers (with caching at each level) to find the IP, which the browser then uses to connect.' },
    ],
  },

  {
    id: 'html',
    label: 'HTML',
    icon: '📄',
    download: false,
    items: [
      { level: 'basic', q: 'What are semantic HTML elements? Why use them?', a: 'Semantic elements clearly describe their meaning — header, nav, main, section, article, aside, footer. They improve accessibility (screen readers), SEO, and code readability compared to generic divs.' },
      { level: 'basic', q: 'Difference between block and inline elements?', a: 'Block elements (div, p, h1) start on a new line and take full width. Inline elements (span, a, img) flow within a line and take only needed width. inline-block combines both (inline flow + width/height).' },
      { level: 'inter', q: 'Difference between id and class?', a: 'An id is unique per page and used for a single element (and JS/anchor targeting). A class can be reused on many elements for shared styling. In CSS, # targets id, . targets class; id has higher specificity.' },
      { level: 'inter', q: 'What is the difference between localStorage, sessionStorage and cookies?', a: 'localStorage persists until cleared (~5-10MB, not sent to server). sessionStorage lasts for the tab session. Cookies (~4KB) are sent with every HTTP request and can have expiry — used for auth/sessions.' },
      { level: 'adv', q: 'What is semantic vs non-semantic and how does HTML help accessibility?', a: 'Semantic tags convey structure and meaning, enabling assistive tech to navigate. Accessibility (a11y) is further improved with alt text on images, proper labels on forms, ARIA roles, and logical heading order.' },
    ],
  },

  {
    id: 'css',
    label: 'CSS',
    icon: '🎨',
    download: false,
    items: [
      { level: 'basic', q: 'Explain the CSS box model.', a: 'Every element is a box with (from inside out): content → padding → border → margin. Total width = content + padding + border + margin. box-sizing: border-box makes width include padding and border, which is easier to manage.' },
      { level: 'basic', q: 'Difference between margin and padding?', a: 'Padding is the space inside the element, between content and border. Margin is the space outside the element, between it and neighbors. Padding affects the element\'s background area; margin does not.' },
      { level: 'inter', q: 'Flexbox vs Grid?', a: 'Flexbox is one-dimensional (row OR column) — great for aligning items in a line, navbars, cards. Grid is two-dimensional (rows AND columns) — great for full page layouts. They can be combined.' },
      { level: 'inter', q: 'Explain CSS position values.', a: 'static (default flow), relative (offset from its normal position), absolute (positioned relative to nearest positioned ancestor), fixed (relative to viewport, stays on scroll), sticky (toggles between relative and fixed based on scroll).' },
      { level: 'inter', q: 'What is specificity in CSS?', a: 'Specificity decides which rule wins when multiple target the same element: inline styles > id > class/attribute/pseudo-class > element. !important overrides all. When equal, the later rule wins.' },
      { level: 'adv', q: 'How do you make a website responsive?', a: 'Use fluid units (%, rem, vw), flexible layouts (flexbox/grid), and media queries to adapt at breakpoints, following a mobile-first approach. Also responsive images and a viewport meta tag. (This site uses exactly these techniques.)' },
      { level: 'adv', q: 'What is glassmorphism in CSS?', a: 'A frosted-glass UI style: a semi-transparent background (rgba), backdrop-filter: blur() to blur what\'s behind, a subtle light border, and soft shadows — giving a translucent, layered look like this website.' },
    ],
  },

  {
    id: 'javascript',
    label: 'JavaScript',
    icon: '🟨',
    download: false,
    items: [
      { level: 'basic', q: 'Difference between var, let and const?', a: 'var is function-scoped and hoisted (can cause bugs). let is block-scoped and reassignable. const is block-scoped and cannot be reassigned (though object contents can still change). Prefer const, then let; avoid var.' },
      { level: 'basic', q: 'Difference between == and ===?', a: '== compares after type coercion (5 == "5" is true). === compares value AND type without coercion (5 === "5" is false). Always prefer === to avoid surprising conversions.' },
      { level: 'basic', q: 'What is the difference between null and undefined?', a: 'undefined means a variable is declared but not assigned (or a missing property). null is an intentional "no value" assigned by the developer. typeof undefined is "undefined"; typeof null is "object" (a known quirk).' },
      { level: 'inter', q: 'What is a closure?', a: 'A closure is a function that remembers variables from its outer (enclosing) scope even after that outer function has returned. It enables data privacy and stateful functions (e.g. counters, once-handlers).' },
      { level: 'inter', q: 'What is hoisting?', a: 'JavaScript moves declarations to the top of their scope before execution. Function declarations and var are hoisted (var initialized as undefined); let/const are hoisted but stay in a "temporal dead zone" until declared, so accessing them early throws.' },
      { level: 'inter', q: 'Explain the event loop.', a: 'JavaScript is single-threaded. The event loop lets it be non-blocking: synchronous code runs on the call stack; async callbacks wait in the task/microtask queue and are pushed to the stack only when it is empty. Promises (microtasks) run before setTimeout (macrotasks).' },
      { level: 'adv', q: 'Callbacks vs Promises vs async/await?', a: 'Callbacks are functions passed to run later but nest badly ("callback hell"). Promises represent a future value with .then()/.catch(), chaining cleanly. async/await is syntactic sugar over promises that lets you write asynchronous code in a synchronous style with try/catch.' },
      { level: 'adv', q: 'What is event bubbling and delegation?', a: 'Bubbling: an event fires on the target then propagates up to ancestors. Event delegation uses this by attaching one listener on a parent to handle events from many children (efficient, works for dynamically added elements).' },
    ],
  },

  {
    id: 'react',
    label: 'React',
    icon: '⚛️',
    download: false,
    items: [
      { level: 'basic', q: 'What is React and what is the Virtual DOM?', a: 'React is a component-based JavaScript library for building UIs. The Virtual DOM is an in-memory copy of the real DOM; React diffs the new virtual DOM against the old one (reconciliation) and updates only what changed, making UI updates fast.' },
      { level: 'basic', q: 'Difference between props and state?', a: 'Props are read-only data passed from parent to child to configure a component. State is internal, mutable data managed within a component (via useState) that triggers a re-render when it changes.' },
      { level: 'basic', q: 'What is JSX?', a: 'JSX is a syntax extension that lets you write HTML-like markup inside JavaScript. It is compiled (by Babel) to React.createElement calls. It makes UI code readable and lets you embed expressions with {}.' },
      { level: 'inter', q: 'Explain useState and useEffect.', a: 'useState adds local state to a functional component and returns the value plus a setter. useEffect runs side effects (data fetching, subscriptions, DOM updates) after render; its dependency array controls when it re-runs, and a returned function handles cleanup.' },
      { level: 'inter', q: 'Why are keys important in lists?', a: 'Keys give list items a stable identity so React can efficiently track which items changed, were added, or removed during reconciliation. Use a unique, stable id — avoid using the array index when the list can reorder.' },
      { level: 'adv', q: 'What is the difference between controlled and uncontrolled components?', a: 'A controlled component has its form value driven by React state (value + onChange). An uncontrolled component keeps its value in the DOM and is read via a ref. Controlled is preferred for validation and predictable data flow.' },
      { level: 'adv', q: 'How do you manage global state / avoid prop drilling?', a: 'Use the Context API (useContext) for app-wide data like theme or auth, or a state management library (Redux, Zustand) for larger apps. This avoids passing props through many intermediate components ("prop drilling").' },
    ],
  },

  {
    id: 'spring',
    label: 'Spring Boot',
    icon: '🌱',
    download: false,
    items: [
      { level: 'basic', q: 'What is Spring Boot vs Spring?', a: 'Spring is a comprehensive Java framework needing lots of configuration. Spring Boot adds auto-configuration, starter dependencies, an embedded server and production-ready features, so you can run a standalone app with minimal setup and no XML.' },
      { level: 'basic', q: 'What does @SpringBootApplication do?', a: 'It combines @Configuration (defines beans), @EnableAutoConfiguration (auto-configures from classpath), and @ComponentScan (scans the package for components). It marks the main class that bootstraps the app.' },
      { level: 'inter', q: 'What is Dependency Injection and IoC?', a: 'Inversion of Control means the Spring container creates and manages objects, not your code. Dependency Injection is how it supplies dependencies — via constructor (preferred), setter, or field with @Autowired — giving loose coupling and testability.' },
      { level: 'inter', q: '@Controller vs @RestController?', a: '@Controller returns view names (for template engines/JSP). @RestController = @Controller + @ResponseBody, so methods return data (JSON/XML) directly in the response body — used for REST APIs.' },
      { level: 'inter', q: 'What is Spring Data JPA?', a: 'An abstraction over JPA/Hibernate that removes DAO boilerplate. Extending JpaRepository gives CRUD methods automatically, plus derived queries (findByEmail) and custom @Query. Hibernate is the underlying ORM mapping entities to tables.' },
      { level: 'adv', q: 'How do you handle exceptions globally?', a: 'With @ControllerAdvice (or @RestControllerAdvice) plus @ExceptionHandler methods that catch exceptions across controllers and return consistent error responses with proper HTTP status via ResponseEntity.' },
      { level: 'adv', q: '@Component vs @Service vs @Repository?', a: 'All register beans. @Component is generic, @Service marks business logic, @Repository marks the data layer and adds persistence-exception translation. They improve readability and enforce layering.' },
      { level: 'adv', q: 'How did you implement authentication in your project?', a: 'In Brew & Bean I used Spring Security for role-based auth — a security filter chain, BCrypt password hashing, and endpoints restricted by role (USER/ADMIN) — and validated these flows with unit and integration tests.' },
    ],
  },

  {
    id: 'hibernate',
    label: 'Hibernate / JPA',
    icon: '💾',
    download: false,
    items: [
      { level: 'basic', q: 'What is ORM and what is Hibernate?', a: 'ORM (Object-Relational Mapping) maps Java objects to database tables so you work with objects instead of SQL. JPA is the specification; Hibernate is the most popular implementation, handling CRUD, caching and lazy loading.' },
      { level: 'basic', q: 'What is the difference between JPA and Hibernate?', a: 'JPA is a specification (a set of interfaces/annotations like @Entity, @Id). Hibernate is a concrete implementation of JPA plus extra features (HQL, caching). You code against JPA and Hibernate provides the engine.' },
      { level: 'inter', q: 'Explain FetchType LAZY vs EAGER.', a: 'LAZY loads related entities only when accessed (better performance, default for collections). EAGER loads them immediately with the parent (default for @ManyToOne). EAGER can cause performance problems by fetching unneeded data.' },
      { level: 'inter', q: 'What is the entity lifecycle in Hibernate?', a: 'Transient (new object, not tracked) → Persistent (attached to a session, changes auto-synced) → Detached (session closed, no longer tracked) → Removed (marked for deletion). The session manages these states.' },
      { level: 'adv', q: 'What is the N+1 query problem and how do you fix it?', a: 'It happens when fetching a list triggers one extra query per item to load related data (1 + N queries). Fix it with JOIN FETCH in JPQL, @EntityGraph, or batch fetching so related data loads in one or few queries.' },
      { level: 'adv', q: 'What is the difference between first-level and second-level cache?', a: 'First-level cache is per-session (enabled by default) — the same entity fetched twice in a session hits the cache. Second-level cache is shared across sessions (optional, e.g. Ehcache) — reduces DB hits for frequently read data application-wide.' },
    ],
  },

  {
    id: 'microservices',
    label: 'Microservices',
    icon: '🧩',
    download: false,
    items: [
      { level: 'basic', q: 'What are microservices?', a: 'An architecture where an app is built as small, independent services, each owning one business capability and its own data, deployable separately and communicating over the network. It contrasts with a monolith (single deployable unit).' },
      { level: 'basic', q: 'Advantages and disadvantages of microservices?', a: 'Advantages: independent scaling/deployment, tech freedom, fault isolation, team autonomy. Disadvantages: distributed-system complexity, network latency, harder debugging, data-consistency challenges, and operational overhead.' },
      { level: 'inter', q: 'How do microservices communicate?', a: 'Synchronously via REST/HTTP or gRPC (RestTemplate, WebClient, OpenFeign), and asynchronously via message brokers (Kafka, RabbitMQ, SQS/SNS). Async messaging decouples services and improves resilience.' },
      { level: 'inter', q: 'What is an API Gateway?', a: 'A single entry point that routes requests to services and handles cross-cutting concerns: authentication, rate limiting, logging, load balancing and response aggregation (e.g. Spring Cloud Gateway). It hides internal topology from clients.' },
      { level: 'inter', q: 'What is service discovery?', a: 'Since instances start/stop with changing IPs, service discovery (Eureka, Consul) lets services register and look up others by name instead of hardcoded addresses, working with client-side load balancing.' },
      { level: 'adv', q: 'What is a circuit breaker?', a: 'A resilience pattern (Resilience4j/Hystrix) that stops calling a failing service after a threshold, "opening" the circuit and returning a fallback quickly instead of waiting for timeouts — preventing cascading failures and allowing recovery.' },
      { level: 'adv', q: 'How do you handle transactions across services?', a: 'Avoid distributed ACID transactions; use the Saga pattern — a sequence of local transactions with compensating actions to undo on failure. It can be choreographed (event-driven) or orchestrated (a coordinator), giving eventual consistency.' },
    ],
  },

  {
    id: 'rest',
    label: 'REST APIs',
    icon: '🔗',
    download: false,
    items: [
      { level: 'basic', q: 'What is a REST API?', a: 'REST is an architectural style for web services over HTTP. Resources are identified by URIs and manipulated with standard HTTP methods, usually exchanging JSON. It is stateless — each request carries all needed information.' },
      { level: 'basic', q: 'What are the main HTTP methods?', a: 'GET (read), POST (create), PUT (full update), PATCH (partial update), DELETE (remove). GET, PUT and DELETE are idempotent; POST is not.' },
      { level: 'basic', q: 'Explain common HTTP status codes.', a: '200 OK, 201 Created, 204 No Content; 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found; 500 Internal Server Error, 503 Service Unavailable. 2xx success, 4xx client error, 5xx server error.' },
      { level: 'inter', q: 'What does stateless mean in REST?', a: 'The server keeps no client session between requests; each request must carry everything needed (like an auth token). This improves scalability because any server instance can handle any request.' },
      { level: 'inter', q: 'PUT vs PATCH?', a: 'PUT replaces the entire resource (idempotent). PATCH applies a partial update to specific fields. Use PUT for full updates, PATCH for changing a few fields.' },
      { level: 'adv', q: 'How do you secure a REST API?', a: 'HTTPS, token-based auth (JWT/OAuth2), input validation, role-based authorization, rate limiting, and correct CORS. Never put sensitive data in URLs; return proper status codes (401/403) for auth failures.' },
      { level: 'adv', q: 'REST vs GraphQL?', a: 'REST exposes fixed endpoints returning fixed structures, risking over/under-fetching. GraphQL exposes one endpoint where the client requests exactly the fields it needs, reducing round trips. REST is simpler and cache-friendly; GraphQL is flexible for nested data.' },
    ],
  },

  {
    id: 'aws',
    label: 'AWS / Cloud',
    icon: '☁️',
    download: true,
    items: [
      { level: 'basic', q: 'What is cloud computing and its service models?', a: 'Cloud computing delivers computing resources (servers, storage, databases) over the internet on demand, pay-as-you-go. Models: IaaS (infrastructure, e.g. EC2), PaaS (platform, e.g. Beanstalk), SaaS (software, e.g. Gmail).' },
      { level: 'basic', q: 'Region vs Availability Zone?', a: 'A Region is a geographic area (e.g. Mumbai). An Availability Zone is one or more isolated data centers within a Region. Deploying across AZs gives high availability — if one AZ fails, others keep serving.' },
      { level: 'basic', q: 'What is AWS Lambda?', a: 'A serverless compute service: you upload a function and AWS runs it in response to events (S3 upload, API Gateway, DynamoDB stream) without managing servers. It auto-scales and you pay per execution (15-min max).' },
      { level: 'basic', q: 'What is Amazon S3?', a: 'S3 is object storage — files (objects) stored in buckets, with 11 nines durability, versioning, lifecycle policies, encryption, static hosting and presigned URLs. Ideal for images, backups and static assets.' },
      { level: 'basic', q: 'What is the shared responsibility model?', a: 'AWS secures the cloud (hardware, networking, managed infrastructure); the customer secures what\'s in the cloud (data, IAM, app config, encryption). Both share the security job.' },
      { level: 'inter', q: 'EC2 vs Lambda — when to use each?', a: 'EC2 is a full server you manage — good for long-running apps, custom environments, steady load. Lambda is serverless, event-driven, auto-scaling and cheap for spiky/short workloads but limited to 15 min and stateless. Lambda for glue/events, EC2 for persistent services.' },
      { level: 'inter', q: 'What is IAM and an IAM Role?', a: 'IAM controls who can do what via Users, Groups, Roles and Policies (JSON, least-privilege). A Role is an identity assumed temporarily — e.g. a Lambda assumes a role to read S3 — so no credentials are hardcoded.' },
      { level: 'inter', q: 'What is Amazon Rekognition (your project)?', a: 'A managed computer-vision service. You send an image (often from S3) and get JSON — faces, emotions, labels, text. In my serverless project an S3 upload triggered Lambda, which called Rekognition to detect emotions at ~95% accuracy without training a model.' },
      { level: 'inter', q: 'S3 vs EBS vs EFS?', a: 'S3 = object storage via API, unlimited scale, for files/backups. EBS = block storage attached to one EC2 instance (a virtual disk). EFS = shared file storage many EC2 instances can mount. Choose by access pattern.' },
      { level: 'inter', q: 'SQS vs SNS?', a: 'SQS is a message queue (point-to-point) — decouples and buffers load, one consumer group processes messages. SNS is pub/sub — one message fans out to many subscribers. They are often combined (SNS → multiple SQS queues).' },
      { level: 'adv', q: 'Explain a serverless architecture you built.', a: 'My Facial Emotion Recognition pipeline: user uploads an image to S3 → the S3 event triggers Lambda → Lambda preprocesses with OpenCV and calls Rekognition to analyze emotions → results stored/returned. It scaled automatically at ~95% accuracy and ~300ms latency, with no servers to manage.' },
      { level: 'adv', q: 'What is a Lambda cold start and how do you reduce it?', a: 'A cold start is the latency when Lambda initializes a new environment (first call or after idle). Reduce it with provisioned concurrency, smaller packages, lighter runtimes, keeping functions warm, and moving heavy init outside the handler for reuse.' },
      { level: 'adv', q: 'How do you monitor and secure AWS applications?', a: 'Monitoring: CloudWatch (logs, metrics, alarms), CloudTrail (API audit), X-Ray (tracing). Security: least-privilege IAM, encryption at rest (KMS) and in transit (TLS), VPC isolation, security groups, Secrets Manager, and MFA.' },
    ],
  },

  {
    id: 'devops',
    label: 'Docker & DevOps',
    icon: '🐳',
    download: false,
    items: [
      { level: 'basic', q: 'What is DevOps?', a: 'DevOps is a culture and set of practices that unite development and operations to deliver software faster and more reliably through automation, continuous integration/delivery, monitoring and collaboration.' },
      { level: 'basic', q: 'What is Docker and why use it?', a: 'Docker packages an app with all its dependencies into a lightweight, portable container that runs the same everywhere. It solves "works on my machine", starts fast, and is more efficient than a VM because it shares the host OS kernel.' },
      { level: 'inter', q: 'Difference between a container and a virtual machine?', a: 'A VM virtualizes hardware and runs a full guest OS (heavy, slow to start). A container virtualizes the OS and shares the host kernel, packaging only the app + dependencies (lightweight, fast, more per host). Containers are ideal for microservices.' },
      { level: 'inter', q: 'Difference between a Docker image and a container?', a: 'An image is a read-only blueprint (app + dependencies) built from a Dockerfile. A container is a running instance of an image. You can run many containers from one image.' },
      { level: 'inter', q: 'What is CI/CD?', a: 'Continuous Integration merges and automatically tests code frequently to catch issues early. Continuous Delivery/Deployment automates releasing that tested code to staging/production. Tools: Jenkins, GitHub Actions, GitLab CI.' },
      { level: 'adv', q: 'What is Kubernetes and why is it used?', a: 'Kubernetes is a container orchestration platform that automates deploying, scaling, load balancing and self-healing of containers across a cluster. Key objects: Pod, Deployment, Service, Node. It manages containers at scale, which Docker alone does not.' },
    ],
  },

  {
    id: 'linux',
    label: 'Linux / Commands',
    icon: '🐧',
    download: false,
    items: [
      { level: 'basic', q: 'Name some common Linux commands.', a: 'ls (list), cd (change dir), pwd (current path), mkdir/rm (create/remove), cp/mv (copy/move), cat/less (view file), grep (search text), find (search files), chmod (permissions), ps/top (processes), kill (stop process).' },
      { level: 'basic', q: 'How do file permissions work in Linux?', a: 'Each file has read (r=4), write (w=2), execute (x=1) permissions for user, group and others. chmod changes them (e.g. 755 = rwx for owner, r-x for group/others); chown changes ownership.' },
      { level: 'inter', q: 'What is a pipe and redirection?', a: 'A pipe | sends one command\'s output as another\'s input (e.g. cat file | grep error). Redirection sends output to files: > overwrites, >> appends, < reads input from a file.' },
      { level: 'inter', q: 'How do you find and kill a process?', a: 'Use ps aux or top to list processes and find the PID, then kill <PID> (or kill -9 <PID> to force). You can also use pkill <name> to kill by process name.' },
    ],
  },

  {
    id: 'sdlc',
    label: 'SDLC / Agile',
    icon: '🔄',
    download: false,
    items: [
      { level: 'basic', q: 'What are the phases of the SDLC?', a: 'Requirement gathering → Design → Implementation (coding) → Testing → Deployment → Maintenance. It provides a structured process for building software.' },
      { level: 'basic', q: 'What is Agile methodology?', a: 'Agile is an iterative, incremental approach that delivers working software in short cycles, welcomes changing requirements, and values customer collaboration and feedback over heavy documentation. Scrum and Kanban are popular frameworks.' },
      { level: 'inter', q: 'Waterfall vs Agile?', a: 'Waterfall is sequential — each phase finishes before the next, with little room for change; good for fixed, well-understood requirements. Agile is iterative and flexible, adapting to change with frequent releases and feedback; better for evolving requirements.' },
      { level: 'inter', q: 'Explain Scrum roles and ceremonies.', a: 'Roles: Product Owner (owns the backlog/priorities), Scrum Master (facilitates, removes blockers), Development Team. Ceremonies: Sprint Planning, Daily Standup, Sprint Review, Retrospective. Work happens in fixed-length Sprints (1–4 weeks).' },
    ],
  },

  {
    id: 'systemdesign',
    label: 'System Design',
    icon: '🏗️',
    download: false,
    items: [
      { level: 'inter', q: 'Vertical vs horizontal scaling?', a: 'Vertical scaling adds more power (CPU/RAM) to one server — simple but has a hard limit and a single point of failure. Horizontal scaling adds more servers behind a load balancer — more scalable and fault-tolerant, but needs statelessness and coordination.' },
      { level: 'inter', q: 'What is a load balancer?', a: 'A component that distributes incoming traffic across multiple servers to improve availability, reliability and performance. Strategies include round robin, least connections, and IP hash. It also enables health checks and failover.' },
      { level: 'inter', q: 'What is caching and where is it used?', a: 'Caching stores frequently accessed data in fast storage (memory) to reduce latency and load. Layers include client/browser cache, CDN (static assets), application cache (Redis/Memcached), and database query cache. Key concerns: invalidation and TTL.' },
      { level: 'adv', q: 'How would you design a URL shortener?', a: 'Generate a short unique key (base62 of an auto-increment id or a hash) mapping to the long URL, store it in a fast key-value DB, redirect (301/302) on lookup. Add caching for hot URLs, sharding for scale, and analytics via async logging.' },
      { level: 'adv', q: 'Database replication vs sharding?', a: 'Replication copies data to multiple nodes (read replicas) for high availability and read scaling. Sharding partitions data horizontally across nodes (by key/range/hash) to scale writes and storage. They are often combined.' },
    ],
  },

  {
    id: 'git',
    label: 'Git / GitHub',
    icon: '🌿',
    download: false,
    items: [
      { level: 'basic', q: 'Git vs GitHub?', a: 'Git is a distributed version-control tool that tracks code changes locally. GitHub is a cloud platform hosting Git repositories with collaboration features (pull requests, issues, reviews, CI/CD). Git is the tool; GitHub is the hosting service.' },
      { level: 'basic', q: 'What is the difference between git merge and git rebase?', a: 'merge combines branches with a merge commit, preserving full history. rebase moves your commits on top of another branch for a linear history but rewrites commit hashes. Use merge on shared branches, rebase to tidy local history before pushing.' },
      { level: 'inter', q: 'git pull vs git fetch?', a: 'fetch downloads remote changes without touching your working branch. pull = fetch + merge, downloading and integrating changes into your current branch. fetch lets you inspect changes first.' },
      { level: 'inter', q: 'How do you resolve a merge conflict?', a: 'Git marks the conflicting sections in files. Open them, choose or combine the correct code, remove the conflict markers (<<<<, ====, >>>>), then git add the resolved files and commit to finish the merge.' },
      { level: 'inter', q: 'git reset vs git revert?', a: 'reset moves HEAD to a previous commit and can discard commits (rewrites history — risky on shared branches). revert creates a new commit that undoes a previous one, keeping history intact — safe for shared branches.' },
    ],
  },

  {
    id: 'testing',
    label: 'Testing / JUnit',
    icon: '🧪',
    download: false,
    items: [
      { level: 'basic', q: 'What is unit testing?', a: 'Unit testing verifies the smallest testable parts (a method/class) in isolation to ensure each behaves correctly. It catches bugs early, supports refactoring, and documents behavior. In Java, JUnit is the standard framework.' },
      { level: 'basic', q: 'What are common JUnit annotations?', a: '@Test marks a test; @BeforeEach/@AfterEach run before/after each test; @BeforeAll/@AfterAll run once per class; @Disabled skips a test. Assertions like assertEquals, assertTrue, assertThrows verify outcomes.' },
      { level: 'inter', q: 'What is the AAA pattern?', a: 'Arrange (set up objects/inputs), Act (call the method under test), Assert (verify the result). It keeps tests readable and focused on one behavior.' },
      { level: 'inter', q: 'What is mocking and why use Mockito?', a: 'Mocking replaces real dependencies (DB, external services) with controllable fakes so a unit is tested in isolation. Mockito stubs behavior (when(...).thenReturn(...)) and verifies interactions (verify(...)), making tests fast and deterministic.' },
      { level: 'adv', q: 'How did you test your Spring Boot projects?', a: 'JUnit unit tests for service logic with Mockito, @DataJpaTest for repository/database validation, and @WebMvcTest with MockMvc for controllers. I prepared structured test data, covered edge cases, verified role-based auth, and documented outcomes.' },
      { level: 'adv', q: 'What is Test-Driven Development (TDD)?', a: 'A cycle: write a failing test first (Red), write minimal code to pass it (Green), then Refactor. It drives better design, ensures coverage, and gives confidence when changing code.' },
    ],
  },

  {
    id: 'security',
    label: 'Cyber Security',
    icon: '🔒',
    download: false,
    items: [
      { level: 'basic', q: 'What is the CIA triad?', a: 'The three pillars of security: Confidentiality (only authorized access), Integrity (data is accurate and unaltered), Availability (systems are accessible when needed). Security measures aim to protect all three.' },
      { level: 'basic', q: 'Authentication vs authorization?', a: 'Authentication verifies WHO you are (login, password, MFA). Authorization determines WHAT you are allowed to do (roles, permissions). Authentication comes first, then authorization.' },
      { level: 'inter', q: 'What is the difference between encryption and hashing?', a: 'Encryption is reversible with a key (symmetric AES / asymmetric RSA) — used to protect data in transit/at rest. Hashing is one-way (SHA-256, bcrypt) — used to store passwords and verify integrity; you compare hashes, never decrypt.' },
      { level: 'inter', q: 'What is SQL injection and how do you prevent it?', a: 'SQL injection inserts malicious SQL via user input to read or alter the database. Prevent it with parameterized queries/prepared statements, ORM usage, input validation, and least-privilege database accounts.' },
      { level: 'adv', q: 'What is XSS and CSRF?', a: 'XSS (Cross-Site Scripting) injects malicious scripts into pages viewed by others — prevent with output encoding and input sanitization. CSRF (Cross-Site Request Forgery) tricks a logged-in user into unwanted actions — prevent with CSRF tokens and SameSite cookies.' },
      { level: 'adv', q: 'What is JWT and how does token-based auth work?', a: 'A JWT (JSON Web Token) is a signed token containing user claims (header.payload.signature). On login the server issues it; the client sends it in the Authorization header on each request; the server verifies the signature — enabling stateless authentication.' },
    ],
  },
]

export const qaMap = Object.fromEntries(qaTopics.map((t) => [t.id, t]))
